import os,re,json
from pathlib import Path

patterns = re.compile(r'13306|ssh\s+-L|172\.31\.6\.193|LocalForward')
roots = [
  Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts'),
  Path('/Users/mac/.dc-platform/memory/mirrors'),
  Path('/Users/mac/.dc-platform/memory/work-log'),
  Path('/Users/mac/.dc-platform/memory/sessions'),
  Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/terminals'),
]
hits=[]
for root in roots:
  if not root.exists():
    continue
  for p in root.rglob('*'):
    if not p.is_file():
      continue
    if p.suffix not in {'.jsonl','.md','.txt','.log',''} and 'terminals' not in str(p):
      continue
    if p.stat().st_size > 50_000_000:
      continue
    try:
      text=p.read_text(encoding='utf-8',errors='ignore')
    except Exception:
      continue
    for i,line in enumerate(text.splitlines(),1):
      if patterns.search(line):
        # prefer lines with ssh
        snip=line.strip().replace('\t',' ')[:240]
        hits.append((str(p), i, snip))
        if len(hits)>=120:
          break
    if len(hits)>=120:
      break

# print ssh-related first
ssh=[h for h in hits if 'ssh' in h[2].lower() or '13306' in h[2] or 'LocalForward' in h[2]]
print('total_hits', len(hits), 'sshish', len(ssh))
for h in ssh[:60]:
  print(f'{h[0]}:{h[1]}: {h[2]}')
print('--- other sample ---')
for h in hits[:20]:
  if h not in ssh[:60]:
    print(f'{h[0]}:{h[1]}: {h[2]}')
